<script setup lang="ts">
import {computed,onMounted,ref,watch} from 'vue'
import {api} from '../services/api'
import type {MentorCatalog} from '../types/mentors'
import ContestEvidence from '../components/ContestEvidence.vue'
import MentorOperations from '../components/MentorOperations.vue'
import SettlementEvidence from '../components/SettlementEvidence.vue'
import LedgerLab from '../components/LedgerLab.vue'
import MentorNotebook from '../components/MentorNotebook.vue'
import Pagination from '../components/Pagination.vue'
import {usePagination} from '../composables/usePagination'
import {formatNumber} from '../utils/format'
const catalog=ref<MentorCatalog|null>(null),busy=ref(true),error=ref(''),active=ref('operations'),search=ref(''),style=ref(''),selected=ref('alias-beihaidadao')
const operationPerson=ref('')
const tabs=[{id:'operations',label:'实盘操作'},{id:'profiles',label:'人物档案'},{id:'evidence',label:'账户与赛期'},{id:'wisdom',label:'语录与心法'},{id:'practice',label:'借鉴验证'},{id:'editions',label:'历届与候选'}]
const profiles=computed(()=>catalog.value?.profiles??[]),person=computed(()=>profiles.value.find(p=>p.id===selected.value)??profiles.value[0])
const identity=ref(''),evidence=ref('')
const styles=computed(()=>[...new Set(profiles.value.map(p=>p.style))])
const filtered=computed(()=>profiles.value.filter(p=>(!style.value||p.style===style.value)&&(!identity.value||(p.identityKind??'PUBLIC_NAME')===identity.value)&&(!evidence.value||(p.researchStatus??'DOCUMENTED')===evidence.value)&&(!search.value||`${p.name} ${p.style} ${p.intro}`.includes(search.value.trim()))))
const {items:people,page:peoplePage,total:peopleTotal}=usePagination(filtered,4,[search,style,identity,evidence])
watch([filtered,active],([rows,tab])=>{if(tab==='profiles'&&rows.length&&!rows.some(p=>p.id===selected.value))selected.value=rows[0]!.id})
const records=computed(()=>person.value?.contestRecords??[])
const {items:recordRows,page:recordPage,total:recordTotal}=usePagination(records,5,[selected])
const sources=computed(()=>catalog.value?.sources??[])
const {items:sourceRows,page:sourcePage,total:sourceTotal}=usePagination(sources,6)
const editions=computed(()=>catalog.value?.editions??[])
const {items:editionRows,page:editionPage,total:editionTotal}=usePagination(editions,10)
const quotes=computed(()=>profiles.value.flatMap(p=>p.quotes.map(q=>({...q,name:p.name}))))
const {items:quoteRows,page:quotePage,total:quoteTotal}=usePagination(quotes,6)
const templates=computed(()=>catalog.value?.learningTemplates.filter(t=>person.value?.learningIds.includes(t.id))??[])
const source=(id:string)=>sources.value.find(s=>s.id===id)
const name=(id:string|null)=>profiles.value.find(p=>p.id===id)?.name??'尚未建档'
const kind:Record<string,string>={FIRST_PERSON_INTERVIEW:'本人采访',FIRST_PERSON_SPEECH:'本人演讲实录',REGULATORY_RECORD:'监管原文',MEDIA_REPORT:'媒体报道',INSTITUTION_VISIT:'机构走访',INSTITUTIONAL_RECORD:'机构原始记录',ISSUER_DISCLOSURE:'发行人披露',ORGANIZER_INTERVIEW:'赛方采访',ORGANIZER_REPORT:'主办方报道',ORGANIZER_RANK_REPRINT:'主办方榜单转载',ORGANIZER_PORTAL:'主办方入口',ORGANIZER_AGGREGATE:'赛方账户汇总',RESEARCH_REPORT:'研究报告'}
const statusText:Record<string,string>={DOCUMENTED:'原始资料已定位',BACKGROUND_ONLY:'背景可查 · 业绩待核',PENDING_MATCH:'昵称匹配待核',PARTIAL_RECORD:'赛期上下文待补'}
const number=(v:number|null,digits=2)=>v==null?'未取得':formatNumber(v,digits)
function openOperations(id:string){operationPerson.value=id;active.value='operations'}
function openProfile(id:string){search.value=profiles.value.find(p=>p.id===id)?.name??'';style.value='';identity.value='';evidence.value='';selected.value=id;active.value='profiles'}
function openAccount(id:string){selected.value=id;active.value='evidence'}
async function load(){busy.value=true;error.value='';try{catalog.value=await api.mentors()}catch(e){error.value=e instanceof Error?e.message:'资料未加载'}finally{busy.value=false}}
onMounted(load)
</script>
<template>
  <div class="mentor-desk">
    <section class="hero"><div><span class="eyebrow">前辈实盘研究 / MENTOR RESEARCH</span><h2>向前辈学习，<br/>向证据求证。</h2><p>成功值得研究，方法需要检验。从已发生的操作、持仓披露和原始访谈出发，理解他们做过什么、承担了什么，以及哪些条件属于那个时代。</p></div><aside><span>我们的学习路径</span><ol><li>核对人物与操作出处</li><li>还原决策、风险与约束</li><li>区分事实、回忆和解释</li><li>用自己的条件验证</li></ol><small>名气与金句，要回到真实操作、风险过程和原始出处。</small></aside></section>
    <p v-if="busy" role="status" class="notice">正在加载人物与实盘证据…</p><div v-if="error" role="alert" class="notice">{{error}} <button type="button" @click="load">重试</button></div>
    <template v-if="catalog">
      <div v-if="catalog.operationSummary" class="stats"><article><strong>{{catalog.summary.profiles}}</strong><span>研究人物与参赛昵称</span></article><article><strong>{{catalog.operationSummary.records}}</strong><span>操作 / 持仓记录片段</span></article><article><strong>{{catalog.summary.aggregateAccounts}}</strong><span>官方公开账户样本</span></article><article><strong>{{catalog.dataCoverage?.netWorthRows??0}}</strong><span>已采集日终净值点</span></article></div>
      <div v-else-if="catalog.dataCoverage" class="stats"><article><strong>{{catalog.summary.aggregateAccounts}}</strong><span>已采集赛方账户</span></article><article><strong>{{catalog.dataCoverage.netWorthRows}}</strong><span>真实日终净值点</span></article><article><strong>{{catalog.dataCoverage.dailyProfitRows}}</strong><span>真实日盈亏记录</span></article><article><strong>{{catalog.dataCoverage.executionRows}}</strong><span>逐笔成交记录 · 尚缺</span></article></div>
      <div v-else class="stats"><article><strong>{{catalog.summary.profiles}}</strong><span>研究条目 · 含待核档案</span></article><article><strong>{{catalog.summary.contestAliases??profiles.filter(p=>p.identityKind==='CONTEST_ALIAS').length}}</strong><span>参赛昵称档案</span></article><article><strong>{{catalog.summary.completePersonLedgers}}</strong><span>完整核验的交割单</span></article><article><strong>{{catalog.sources.length}}</strong><span>可追溯资料来源</span></article></div>
      <p v-if="catalog.operationSummary" class="definition">已收录 {{catalog.operationSummary.profiles}} 位研究对象的操作片段：{{catalog.operationSummary.regulatoryRecords}} 条监管披露、{{catalog.operationSummary.recalledRecords}} 条本人回忆。另有 {{catalog.dataCoverage?.dailyProfitRows??0}} 条日盈亏、{{catalog.dataCoverage?.breedRows??0}} 行品种汇总与 {{catalog.dataCoverage?.settlementRows??0}} 行独立账户资金表。操作片段、账户统计和成交账单分别呈现，不以拿到完整交割单作为研究入口。</p>
      <p class="definition">{{catalog.definition}}</p>
      <div class="tabs" role="tablist" aria-label="前辈研究栏目"><button v-for="t in tabs" :id="`tab-${t.id}`" :key="t.id" role="tab" :aria-selected="active===t.id" :aria-controls="`panel-${t.id}`" @click="active=t.id">{{t.label}}</button></div>
      <section v-if="active==='operations'" id="panel-operations" role="tabpanel" aria-labelledby="tab-operations"><MentorOperations :records="catalog.operations??[]" :profiles="profiles" :sources="sources" :version="catalog.version" :preferred-profile-id="operationPerson" @profile="openProfile" @account="openAccount"/></section>
      <section v-if="active==='profiles'" id="panel-profiles" role="tabpanel" aria-labelledby="tab-profiles">
        <div class="section-title"><div><span class="eyebrow">官方昵称与具名人物均可研究</span><h3>人物档案</h3></div><div class="filters"><input v-model="search" type="search" aria-label="搜索前辈" placeholder="搜索姓名、昵称…"/><select v-model="identity" aria-label="筛选档案类型"><option value="">全部身份形式</option><option value="CONTEST_ALIAS">参赛昵称</option><option value="PUBLIC_NAME">公开具名</option></select><select v-model="evidence" aria-label="筛选证据状态"><option value="">全部证据状态</option><option v-for="(text,value) in statusText" :key="value" :value="value">{{text}}</option></select><select v-model="style" aria-label="筛选交易风格"><option value="">全部研究方向</option><option v-for="s in styles" :key="s">{{s}}</option></select></div></div>
        <div class="people"><button v-for="p in people" :key="p.id" type="button" class="person-card" :class="{chosen:person?.id===p.id}" :aria-pressed="person?.id===p.id" @click="selected=p.id"><span class="monogram">{{p.initials}}</span><span><strong>{{p.name}}</strong><small>{{p.style}}</small><em>{{p.admission}}</em></span></button></div><p v-if="!peopleTotal" class="notice">没有匹配人物。</p><Pagination v-model:page="peoplePage" :page-size="4" :total="peopleTotal" label="人物档案分页"/>
        <article v-if="person&&peopleTotal" class="profile-detail"><div class="profile-heading"><div><span class="eyebrow">{{person.identityStatus}}</span><h3>{{person.name}}</h3><span class="badge">{{statusText[person.researchStatus??'DOCUMENTED']}}</span><p>{{person.intro}}</p></div><div class="profile-actions"><button type="button" @click="openOperations(person.id)">查看实盘操作 · {{person.operationIds?.length??0}}</button><button type="button" @click="active='evidence'">账户与赛期 →</button></div></div><p v-if="person.identityNotes" class="muted">{{person.identityNotes}}</p><div class="evidence-strip"><div><b>实盘参与</b><span>{{person.liveEvidence}}</span></div><div><b>成功阶段证据</b><span>{{person.successEvidence}}</span></div></div><div class="biography"><section><h4>经历与时代背景</h4><article v-for="(entry,i) in person.timeline" :key="i" class="timeline"><strong>{{entry.period}}</strong><p>{{entry.fact}}</p><a v-for="id in entry.sourceIds" :key="id" :href="source(id)?.url" target="_blank" rel="noopener noreferrer">{{source(id)?.publisher}} ↗</a></article><p v-if="!person.timeline.length" class="muted">当前没有足够可靠的完整履历；保留昵称即可研究，不追查个人隐私。</p></section><section><h4>突出事迹与证据边界</h4><article v-for="(a,i) in person.achievements" :key="i" class="achievement"><p>{{a.text}}</p><a v-for="id in a.sourceIds" :key="id" :href="source(id)?.url" target="_blank" rel="noopener noreferrer">查看原始资料 ↗</a></article><p class="missing">{{person.ledger.message}}</p></section></div></article>
      </section>
      <section v-if="active==='evidence'" id="panel-evidence" role="tabpanel" aria-labelledby="tab-evidence" class="stack">
        <div class="section-title"><div><span class="eyebrow">原件、汇总与传述分别呈现</span><h3>实盘证据研究</h3></div><label>人物<select v-model="selected" aria-label="选择证据人物"><option v-for="p in profiles" :key="p.id" :value="p.id">{{p.name}}</option></select></label></div>
        <article v-if="person" class="missing-panel"><h4>{{person.name}} · {{person.linkedAccountId?'已取得官方账户数据':'账户资料与操作记录分开研究'}}</h4><p>{{person.linkedAccountId?person.ledger.message:'暂未对应官方账户统计；可先查看已定位的操作片段、原始访谈或赛期记录。'}}</p><button type="button" @click="openOperations(person.id)">查看该人物操作记录 · {{person.operationIds?.length??0}}</button><details><summary>完整账户核算仍需哪些资料</summary><p>{{person.ledger.missing.join('、')}}</p></details><p v-if="person.linkedAccountId">下方默认选中该昵称对应的本届本组公开账户；无需实名，汇总与逐笔记录分别研究。</p><p v-else>下方汇总是独立账户样本，尚未与此档案建立公开记录对应；不能归入{{person.name}}的实盘业绩。</p></article>
        <article v-if="recordTotal" class="record-panel"><h4>{{person?.name}} · 赛期记录</h4><p class="muted">赛中排名与最终名次报道分开。金额为原文净利润字段，回撤未由本系统复算；账户ID缺失时不拼接曲线，不跨届按昵称归并。</p><div class="table-wrap"><table><thead><tr><th>届次 / 组别</th><th>记录时点</th><th>名次口径</th><th>净利润（元）</th><th>累计净值</th><th>赛方回撤率</th><th>出处</th></tr></thead><tbody><tr v-for="r in recordRows" :key="r.recordKey"><td>第{{r.edition??'待核'}}届 / {{r.group}}<small>{{r.year??'年份待核'}}</small></td><td>{{r.asOf??'最终名次报道'}}</td><td>{{r.scope==='FINAL_REPORTED'?'最终名次报道':'赛中/采集时点'}} · {{r.rank==null?'待核':`第${r.rank}名`}}</td><td>{{number(r.netProfit)}}</td><td>{{number(r.cumulativeNetWorth,5)}}</td><td>{{r.reportedDrawdownPct==null?'未取得':`${number(r.reportedDrawdownPct,3)}%`}}</td><td><a v-for="id in r.sourceIds" :key="id" :href="source(id)?.url" target="_blank" rel="noopener noreferrer">原文 ↗</a></td></tr></tbody></table></div><Pagination v-model:page="recordPage" :page-size="5" :total="recordTotal" label="赛期记录分页"/></article>
        <p v-else-if="person?.identityKind==='CONTEST_ALIAS'" class="notice">该昵称尚缺可精确归属的赛期记录，不套用相近昵称的成绩。</p>
        <ContestEvidence :snapshot="catalog.contestSnapshot" :preferred-account-id="person?.linkedAccountId"/><SettlementEvidence v-if="catalog.settlementSnapshot" :snapshot="catalog.settlementSnapshot"/><details class="optional-ledger"><summary>已有成交账单？展开逐笔核算工具</summary><LedgerLab/></details>
      </section>
      <section v-if="active==='wisdom'" id="panel-wisdom" role="tabpanel" aria-labelledby="tab-wisdom" class="stack">
        <div class="section-title"><div><span class="eyebrow">保留语境，避免神化</span><h3>原话与研究者归纳</h3></div></div><p class="muted">只收录能定位原文的短句。找不到原话，就留空；归纳的方法不会署作本人语录。</p>
        <div class="quote-grid"><figure v-for="q in quoteRows" :key="q.name+q.text" class="quote"><blockquote>“{{q.text}}”</blockquote><figcaption>{{q.name}} · 本人专访</figcaption><p>{{q.context}}</p><a :href="source(q.sourceId)?.url" target="_blank" rel="noopener noreferrer">回到原文与语境 ↗</a></figure></div><Pagination v-model:page="quotePage" :page-size="6" :total="quoteTotal" label="语录分页"/>
        <label class="person-picker">研究对象<select v-model="selected" aria-label="选择心法人物"><option v-for="p in profiles" :key="p.id" :value="p.id">{{p.name}}</option></select></label><p v-if="!person?.quotes.length" class="missing">{{person?.name}}：当前未取得足够可靠的原话出处，不收录流传金句。</p><article v-for="m in person?.methods" :key="m.title" class="method"><span class="eyebrow">{{m.status}}</span><h4>{{m.title}}</h4><p>{{m.body}}</p><a v-for="id in m.sourceIds" :key="id" :href="source(id)?.url" target="_blank" rel="noopener noreferrer">{{source(id)?.publisher}} ↗</a></article><p v-if="!person?.methods.length" class="missing">方法证据尚不足，不从获奖名次推测其交易心法。</p>
      </section>
      <section v-if="active==='practice'" id="panel-practice" role="tabpanel" aria-labelledby="tab-practice" class="stack">
        <div class="section-title"><div><span class="eyebrow">从故事走向检验</span><h3>哪些值得学，怎样验证</h3></div><label>研究对象<select v-model="selected" aria-label="选择借鉴人物"><option v-for="p in profiles" :key="p.id" :value="p.id">{{p.name}}</option></select></label></div>
        <article v-for="f in person?.factors" :key="f.factor" class="factor"><div><h4>{{f.factor}}</h4><span class="badge">{{f.status}}</span></div><p>{{f.evidence}}</p><div class="factor-columns"><section><h5>可以学习的过程</h5><p>{{f.learn}}</p></section><section><h5>不能直接搬用的条件</h5><p>{{f.cannotCopy}}</p></section><section><h5>还可能有哪些解释</h5><p>{{f.alternative}}</p></section></div></article>
        <p class="missing">阶段盈利不能区分能力、环境与运气的占比。缺少完整资金流、失败者对照和预留样本时，“已证明可复制”不成立。</p><MentorNotebook v-if="person" :templates="templates" :person="person.name" :person-id="person.id" :legacy-name-match="person.identityKind!=='CONTEST_ALIAS'"/>
      </section>
      <section v-if="active==='editions'" id="panel-editions" role="tabpanel" aria-labelledby="tab-editions" class="stack">
        <div class="section-title"><div><span class="eyebrow">持续建设的档案索引</span><h3>历届实盘大赛与民间样本</h3></div></div><p class="muted">这是第一至二十届的资料缺口索引，尚非完整获奖名录。只有原文明确记载的届次与年份才填写。全球赛与全国赛分别核对，不混用届次。</p>
        <div class="table-wrap"><table><thead><tr><th>全国赛届次</th><th>已定位年份</th><th>已建档人物 / 昵称</th><th>当前资料</th><th>核对入口</th></tr></thead><tbody><tr v-for="e in editionRows" :key="e.edition"><td>第{{e.edition}}届</td><td>{{e.year??'待核验'}}</td><td>{{e.profileIds?.length?e.profileIds.map(id=>name(id)).join('、'):name(e.profileId)}}</td><td>{{e.status==='ARCHIVE_PENDING'?'历史档案待补':e.status==='PUBLIC_SNAPSHOT'?'赛方公开汇总，非全体名单':'部分人物/昵称记录，非完整获奖记录'}}</td><td><a :href="e.url" target="_blank" rel="noopener noreferrer">主办方入口 ↗</a></td></tr></tbody></table></div><Pagination v-model:page="editionPage" :page-size="10" :total="editionTotal" label="历届大赛分页"/>
        <article class="candidate"><h4>以证据建档，尊重参赛昵称</h4><p>官方昵称可独立进入研究档案，无需公开或追查实名。已采集的 {{catalog.contestSnapshot.accounts.length}} 个公开汇总账户也已按本届本组记录建档；没有完整交割单的事实单独标注。</p><ol><li>核对主办方、赛事届次、组别和公开账户记录</li><li>区分赛中排名与最终名次，不按相近昵称自动归并</li><li>说明成功阶段，核对完整期间、费用与资金流</li><li>保留亏损、未获奖及退出时期，再检验可借鉴性</li></ol><p>资料已定位 {{catalog.summary.documentedProfiles??'—'}} 项；背景可查但个人业绩待核 {{catalog.summary.backgroundProfiles??'—'}} 项；昵称匹配或赛期上下文待核 {{catalog.summary.pendingProfiles??'—'}} 项。资料已定位不是收益认证。</p><button type="button" @click="active='evidence'">查看真实公开样本 →</button></article>
      </section>
      <details class="sources"><summary>资料来源与证据规则 · {{catalog.sources.length}} 项</summary><ul class="policies"><li v-for="p in catalog.evidencePolicy" :key="p">{{p}}</li></ul><article v-for="s in sourceRows" :key="s.id" class="source"><div><span class="badge">{{kind[s.kind]??s.kind}}</span><span>{{s.publisher}}</span></div><a :href="s.url" target="_blank" rel="noopener noreferrer">{{s.title}} ↗</a><p>{{s.limitation}}</p><small>原文日期 {{s.publishedAt??'未核准'}} · 核对日期 {{s.checkedAt}}</small></article><Pagination v-model:page="sourcePage" :page-size="6" :total="sourceTotal" label="人物资料来源分页"/></details>
    </template>
  </div>
